import ExcelJS from 'exceljs';

export const exportToExcel = (projectDetails, sections) => {
    const workbook = new ExcelJS.Workbook();
    const worksheet = workbook.addWorksheet('Project Details');

    // Function to apply styles to cells
    const applyStyles = (cell, style) => {
        cell.alignment = { vertical: 'middle', horizontal: 'center' }; // Center align content
        cell.font = { bold: true, size: style.fontSize || 12 }; // Default font size is 12
        cell.border = {
            top: { style: 'thin' },
            left: { style: 'thin' },
            bottom: { style: 'thin' },
            right: { style: 'thin' }
        };
        if (style.backgroundColor) {
            cell.fill = {
                type: 'pattern',
                pattern: 'solid',
                fgColor: { argb: style.backgroundColor }
            };
        }
        cell.numFmt = style.format || undefined; // Number format
        if (style.rowHeight) {
            worksheet.getRow(cell.row).height = style.rowHeight; // Set row height
        }
        if (style.columnWidth) {
            worksheet.getColumn(cell.col).width = style.columnWidth; // Set column width
        }
    };

    // Add project details to the worksheet
    const projectDetailsRows = [
        ['Project Name', projectDetails.projectName],
        ['Client', projectDetails.client],
        ['Contractor', projectDetails.contractor],
        ['Consultant', projectDetails.consultant],
        ['Title', projectDetails.title]
    ];

    projectDetailsRows.forEach((row) => {
        const worksheetRow = worksheet.addRow(row);
        worksheetRow.eachCell((cell) => {
            applyStyles(cell, { backgroundColor: 'FFCC99', fontSize: 14, rowHeight: 20, columnWidth: 30 });
        });
    });

    worksheet.addRow([]); // Empty row for spacing

    // Function to add sections and their data to the worksheet
    const addDataToSectionsSheet = (section) => {
        const sectionStartRow = worksheet.rowCount + 1;

        // Add section name with specific style
        const sectionNameCell = worksheet.getCell(`A${sectionStartRow}`);
        sectionNameCell.value = `Section Name: ${section.section_name}`;
        applyStyles(sectionNameCell, { backgroundColor: 'FFFF99', fontSize: 14, rowHeight: 20, columnWidth: 30 });

        // Merge cells to center the section name
        worksheet.mergeCells(`A${sectionStartRow}:B${sectionStartRow}`);

        worksheet.addRow([]); // Empty row for spacing

        if (section.subsections) {
            section.subsections.forEach((subsection) => {
                const subsectionStartRow = worksheet.rowCount + 1;

                // Add subsection name with specific style
                const subsectionNameCell = worksheet.getCell(`A${subsectionStartRow}`);
                subsectionNameCell.value = `Subsection Name: ${subsection.subsection_name}`;
                applyStyles(subsectionNameCell, { backgroundColor: 'FFFFCC', fontSize: 12, rowHeight: 18, columnWidth: 25 });

                // Merge cells to center the subsection name
                worksheet.mergeCells(`A${subsectionStartRow}:B${subsectionStartRow}`);

                worksheet.addRow([]); // Empty row for spacing

                if (subsection.documents) {
                    // Add a table for documents
                    const documentTableHeaders = [
                        'Document Name',
                        'Start Date',
                        'End Date',
                        'Status',
                        'Priority',
                        'Assigned To',
                        'Progress'
                    ];
                    const documentTable = worksheet.addTable({
                        name: `Documents_${section.section_name}_${subsection.subsection_name}`,
                        ref: `A${worksheet.rowCount + 1}`,
                        headerRow: true,
                        totalsRow: false,
                        style: {
                            theme: 'TableStyleMedium9',
                            showRowStripes: true
                        },
                        columns: documentTableHeaders.map((header) => ({ name: header, filterButton: true })),
                        rows: []
                    });

                    subsection.documents.forEach((document) => {
                        const documentRow = [
                            `${document.serial_number}-${document.document_name}`,
                            document.start_date || 'N/A',
                            document.end_date || 'N/A',
                            document.status || 'N/A',
                            document.priority || 'N/A',
                            document.assigned_to || 'N/A',
                            document.progress || 'N/A'
                        ];
                        documentTable.addRow(documentRow);
                    });

                    worksheet.addRow([]); // Empty row for spacing
                }
            });
        }
    };

    // Iterate over sections and add their data
    if (sections) {
        sections.forEach((section) => {
            addDataToSectionsSheet(section);
        });
    }

    // Save the workbook
    workbook.xlsx.writeBuffer().then((buffer) => {
        const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `${projectDetails.projectName}_Details.xlsx`;
        a.click();
        URL.revokeObjectURL(url);
    });
};
